inputs = ['ejwci', 'vfcvwv', 'kebz', 'fj', 'cja']
outputs = ['ejigvici', 'vfcvigviv', 'kebjh', 'fj', 'cjv']

print("Input -> Output analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")

# Let's check which characters change
print("\nCharacter-by-character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        elif j < len(inp):
            print(f"  Position {j}: '{inp[j]}' (removed)")
        elif j < len(outp):
            print(f"  Position {j}: '{outp[j]}' (added)")

